app.addEventListener('input',e=>{if(!e.target.matches('[data-admin-global-search]'))return;const box=app.querySelector('#admin-search-results'),q=e.target.value.trim().toLocaleLowerCase('ro'),d=window.tunsproAdminData||{};if(!box)return;if(q.length<2){box.hidden=true;box.innerHTML='';return}const candidates=[...(d.shops||[]).map(x=>({title:x.name,detail:'Frizerie · '+x.city,route:'admin-shops',text:[x.name,x.city,x.address,x.phone].join(' ')})),...(d.owners||[]).map(x=>({title:x.owner||x.shop_name,detail:'Cont frizerie · '+x.email,route:'admin-users',text:[x.owner,x.shop_name,x.email,x.city].join(' ')})),...(d.customers||[]).map(x=>({title:x.name,detail:'Client · '+x.email+' · '+x.phone,route:'admin-users',text:[x.name,x.email,x.phone].join(' ')})),...(d.staff||[]).map(x=>({title:x.name,detail:'Frizer · '+x.shop_name,route:'admin-staff',text:[x.name,x.shop_name,x.city].join(' ')})),...(d.bookings||[]).map(x=>({title:x.client,detail:'Programare · '+x.shop_name+' · '+x.service_name,route:'admin-bookings',text:[x.client,x.phone,x.shop_name,x.staff_name,x.service_name].join(' ')}))].filter(x=>x.text.toLocaleLowerCase('ro').includes(q)).slice(0,8);box.innerHTML=candidates.length?candidates.map(x=>'<button type="button" data-admin-search-result data-route="'+x.route+'" data-query="'+esc(q)+'"><strong>'+esc(x.title)+'</strong><small>'+esc(x.detail)+'</small></button>').join(''):'<p>Nu am găsit rezultate pentru „'+esc(q)+'”.</p>';box.hidden=false});
function applyAdminFilters(){if(!location.hash.startsWith('#admin'))return;const search=([...app.querySelectorAll('[data-admin-search]')].map(x=>x.value.trim()).find(Boolean)||'').toLocaleLowerCase('ro');const filters=[...app.querySelectorAll('[data-admin-filter]')].filter(el=>el.value).map(el=>[el.dataset.adminFilter,el.value]);let rangeStart='',rangeEnd='';const dateValue=app.querySelector('[data-calendar-date]')?.value,view=app.querySelector('[data-calendar-view]')?.value;if(dateValue){const base=new Date(String(dateValue)+'T12:00:00');if(view==='week'){const day=(base.getDay()+6)%7;base.setDate(base.getDate()-day);rangeStart=base.toLocaleDateString('en-CA');base.setDate(base.getDate()+7);rangeEnd=base.toLocaleDateString('en-CA')}else if(view==='month'){base.setDate(1);rangeStart=base.toLocaleDateString('en-CA');base.setMonth(base.getMonth()+1);rangeEnd=base.toLocaleDateString('en-CA')}else{rangeStart=dateValue;const next=new Date(String(dateValue)+'T12:00:00');next.setDate(next.getDate()+1);rangeEnd=next.toLocaleDateString('en-CA')}}for(const row of app.querySelectorAll('[data-admin-record]')){const matchesSearch=!search||(row.dataset.search||'').includes(search);const matchesFilters=filters.every(([key,value])=>(row.dataset[key]||'')===value);const date=row.dataset.date||'';const matchesRange=!rangeStart||date>=rangeStart&&date<rangeEnd;row.hidden=!(matchesSearch&&matchesFilters&&matchesRange)}}
app.addEventListener('input',e=>{if(e.target.matches('[data-admin-search]')){for(const input of app.querySelectorAll('[data-admin-search]'))if(input!==e.target)input.value=e.target.value;applyAdminFilters()}});
app.addEventListener('change',e=>{if(e.target.matches('[data-admin-filter],[data-calendar-date],[data-calendar-view]'))applyAdminFilters();if(e.target.matches('[data-admin-dashboard-range]')){const d=window.tunsproAdminData||{},days=e.target.value==='7'?(d.booking_activity||[]):d.booking_activity_30||[];const chart=app.querySelector('.admin-line-wrap')?.parentElement;if(chart)chart.innerHTML=adminLineChart(days);const title=app.querySelector('#admin-booking-chart-title');if(title)title.textContent=`Programări · ultimele ${days.length} zile`}});
